cd /home/claude/build && python3 - <<'EOF'
import re
m=open('SPEC_MERGED.md').read()
sec=m.split('# II · THE CHANNELS')[1].split('# III ·')[0]
rows=[l.split('|')[1:-1] for l in sec.split('\n') if re.match(r'\| [A-Z][a-z]? [IVX]+',l)]
rows=[[c.strip() for c in r] for r in rows]
star=[r for r in rows if r[0].endswith('*')]; full=[r for r in rows if not r[0].endswith('*')]
def n(x): 
    try: return int(x)
    except: return 0
def brk(x):
    a,b=x.split('/'); return int(a),int(b)
def summarise(rs):
    el={r[0].rstrip('* ').split()[0] for r in rs}; sp={r[0].rstrip('* ') for r in rs}
    lev=sum(n(r[3]) for r in rs); inter=sum(n(r[4]) for r in rs)
    ok=sum(brk(r[5])[0] for r in rs if '/' in r[5]); tot=sum(brk(r[5])[1] for r in rs if '/' in r[5]); unt=sum(1 for r in rs if 'untested' in r[5])
    return dict(rows=len(rs),elements=len(el),species=len(sp),levels=lev,interior=inter,bracket=f'{ok}/{tot}',untested_rows=unt)
print('ALL  ',summarise(rows)); print('FULL ',summarise(full)); print('STAR ',summarise(star))
EOF

